// Package assets embeds the built dashboard files that the local daemon serves.
//
// index.html and local-console.js are generated by the Bun pipeline in this
// directory (build.sh / build.ps1) and committed to the repository, so Go
// builds never need a Bun runtime. See docs/Dashboard-rewrite-plan.md.
package assets

import "embed"

// Content holds the dashboard assets served at GET / and GET /local-console.js.
//
//go:embed index.html local-console.js
var Content embed.FS
